-- Root-only exact reviewed registration. Caller starts transaction and chooses COMMIT/ROLLBACK.
DO $register$
DECLARE a population_top3000_202608_202609_v1.acquisition_control%rowtype;p population_top3000_202608_202609_v1.pipeline_control%rowtype;asgn jsonb;cl jsonb;rev jsonb;actual jsonb;aid bigint;cid bigint;bh text;old record;fn regprocedure;fh text;before_state jsonb;after_state jsonb;released jsonb;BEGIN
 PERFORM pg_advisory_xact_lock(2026083000261022);
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton FOR UPDATE;
 IF a.owner_id IS DISTINCT FROM 'top3000-completion-20261024-root-5db48b32d103' OR a.owner_fence IS DISTINCT FROM 3 OR a.stop_generation IS DISTINCT FROM 1 OR a.enabled IS DISTINCT FROM true OR a.stopped IS DISTINCT FROM false OR a.hold_reason IS NOT NULL OR p.enabled IS DISTINCT FROM true OR p.expected_owner_id IS DISTINCT FROM a.owner_id OR p.expected_owner_fence IS DISTINCT FROM 3 OR p.expected_stop_generation IS DISTINCT FROM 1 OR a.admitted_until IS NULL OR a.admitted_until<=clock_timestamp() OR p.deadline IS NULL OR p.deadline<=clock_timestamp() OR a.scope_sha256 IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR p.scope_sha256 IS DISTINCT FROM a.scope_sha256 OR p.budget_evidence#>>'{monetary_policy,authority_event_id}' IS DISTINCT FROM '9528' THEN RAISE EXCEPTION 'CTX07_V8_CURRENT_AUTHORITY';END IF;
 SELECT event_id,details INTO aid,asgn FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5' AND details->>'assignment_id'='ctx07-four-retained-jolts-byte-parser-v8' ORDER BY event_id DESC LIMIT 1;
 SELECT event_id,details INTO cid,cl FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND details->>'assignment_event_id'=aid::text ORDER BY event_id DESC LIMIT 1;
 IF aid IS DISTINCT FROM 19733 OR cid IS DISTINCT FROM 19742 OR asgn->>'owner_id' IS DISTINCT FROM a.owner_id OR asgn->>'owner_fence' IS DISTINCT FROM '3' OR asgn->>'stop_generation' IS DISTINCT FROM '1' OR asgn->>'scope_sha256' IS DISTINCT FROM a.scope_sha256 OR asgn->>'assigned_executor' IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR asgn->>'root_will_not_concurrently_modify' IS DISTINCT FROM 'true' OR asgn->>'exclusive_component' IS DISTINCT FROM 'CTX07_EXACT_FOUR_JOLTS_BYTE_PARSER_V8' OR asgn#>>'{bounds,http_requests}' IS DISTINCT FROM '0' OR (asgn->>'not_after')::timestamptz<=clock_timestamp() OR asgn->>'not_after' IS NULL OR cl->>'assignment_details_sha256' IS DISTINCT FROM encode(sha256(convert_to(asgn::text,'UTF8')),'hex') OR cl->>'owner_id' IS DISTINCT FROM a.owner_id OR cl->>'owner_fence' IS DISTINCT FROM '3' OR cl->>'stop_generation' IS DISTINCT FROM '1' OR cl->>'scope_sha256' IS DISTINCT FROM a.scope_sha256 OR cl->>'expires_at' IS NULL OR (cl->>'expires_at')::timestamptz<=clock_timestamp() OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND details->>'claim_event_id'=cid::text) THEN RAISE EXCEPTION 'CTX07_V8_EXACT_LIVE_CLAIM';END IF;
 IF population_top3000_202608_202609_v1.ctx07_recovery_bundle_v6() IS DISTINCT FROM '0d2aa25a50603da0fc5f00bf4eea5419fe56f368244cef73de08c21ea70dbe4f' THEN RAISE EXCEPTION 'CTX07_V8_OLD_BUNDLE_PREIMAGE';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX07' AND stage IN('NORMALIZE','DERIVE','VALIDATE') AND status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease l JOIN population_top3000_202608_202609_v1.pipeline_attempt z USING(attempt_id) JOIN population_top3000_202608_202609_v1.pipeline_task t USING(task_id) JOIN population_top3000_202608_202609_v1.ctx07_recovery_request_v6 r ON r.request_key=t.partition_key JOIN population_top3000_202608_202609_v1.ctx07_jolts_scope_v8() s USING(source_id) WHERE l.released_at IS NULL) THEN RAISE EXCEPTION 'CTX07_V8_UNRECONCILED_OPERATION';END IF;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_task t JOIN population_top3000_202608_202609_v1.ctx07_jolts_scope_v8() s ON s.normalize_task_id=t.task_id JOIN population_top3000_202608_202609_v1.pipeline_attempt z ON z.attempt_id=t.attempt_id WHERE t.status='BLOCKED' AND t.blocker_code='PARSER' AND t.stage='NORMALIZE' AND t.lease_until IS NULL AND t.last_failure_class='PARSER' AND t.resumption_condition#>>'{details,sqlstate}'='22021' AND z.ended_at IS NOT NULL AND z.outcome<>'RUNNING')<>4 THEN RAISE EXCEPTION 'CTX07_V8_EXACT_FOUR_PARSER_HOLDS';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ctx07_recovery_evidence_v6 e JOIN population_top3000_202608_202609_v1.ctx07_recovery_request_v6 r USING(request_key) JOIN population_top3000_202608_202609_v1.ctx07_jolts_scope_v8() s USING(source_id)) THEN RAISE EXCEPTION 'CTX07_V8_PREEXISTING_EVIDENCE_REVIEW';END IF;
 bh:=population_top3000_202608_202609_v1.ctx07_jolts_bundle_v8();
 SELECT details INTO rev FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CTX07_V8_JOLTS_INDEPENDENT_REVIEW' AND details->>'bundle_sha256'=bh ORDER BY event_id DESC LIMIT 1;
 SELECT details INTO actual FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CTX07_V8_JOLTS_ACTUAL_ROLLBACK' AND details->>'bundle_sha256'=bh ORDER BY event_id DESC LIMIT 1;
 IF rev->>'code_commit' IS NULL OR rev->>'code_commit' !~ '^[0-9a-f]{40}$' OR actual->>'code_commit' IS DISTINCT FROM rev->>'code_commit' OR rev->>'approved' IS DISTINCT FROM 'true' OR nullif(rev->>'reviewer','') IS NULL OR rev->>'reviewer' IS NOT DISTINCT FROM rev->>'producer' OR actual->>'result' IS DISTINCT FROM 'PASS_CTX07_V8_JOLTS_PRIVATE_ROLLBACK' OR actual->>'verified_units' IS DISTINCT FROM '7' OR actual->>'all_production_changes_rolled_back' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'CTX07_V8_REVIEW_AND_RUNTIME_PROOF_REQUIRED';END IF;
 before_state:=jsonb_build_object('provider_requests',a.provider_requests,'http_invocations',a.http_invocations,'stored_bytes',a.stored_bytes,'reserved_bytes',a.reserved_bytes,'admitted_until',a.admitted_until,'deadline',p.deadline,'tasks',(SELECT jsonb_agg(jsonb_build_object('task_id',t.task_id,'executions',t.executions,'cumulative_failures',t.cumulative_failures,'same_failure_count',t.same_failure_count,'last_failure_fingerprint',t.last_failure_fingerprint,'checkpoint',t.checkpoint) ORDER BY t.task_id) FROM population_top3000_202608_202609_v1.pipeline_task t JOIN population_top3000_202608_202609_v1.ctx07_jolts_scope_v8() s ON s.normalize_task_id=t.task_id));
 FOR old IN SELECT * FROM(VALUES('NORMALIZE','3a3fc0b232048dcbff4b3a2d7e67818bef26651a36debdfbb699d3b58156ba99'),('DERIVE','401a6aec34d3d7b3a63aa6cb73f77dd37bdf5c65c261cf3ca5982e7fb5bffde7'),('VALIDATE','eddd750a2bc03d326bce7e3bbd25078e9eb0bc40229a8e10f60cefcd665c78a9'))v(stage,hash) LOOP
 PERFORM 1 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='CTX07' AND stage=old.stage AND function_sha256=old.hash AND function_sha256=encode(sha256(convert_to(pg_get_functiondef(function_oid),'UTF8')),'hex') FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'CTX07_V8_ADAPTER_PREIMAGE';END IF;
 fn:=('population_top3000_202608_202609_v1.ctx07_recovery_'||lower(old.stage)||'_v8(uuid,text)')::regprocedure;fh:=encode(sha256(convert_to(pg_get_functiondef(fn),'UTF8')),'hex');
 UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET function_oid=fn,function_sha256=fh,producer_revision='ctx07-jolts-byte-v8',reviewed_test_evidence=coalesce(reviewed_test_evidence,'{}')||jsonb_build_object('jolts_v8_review',rev,'jolts_v8_actual_rollback',actual) WHERE family_id='CTX07' AND stage=old.stage;
 END LOOP;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX07_V8_JOLTS_PARSER_ADMISSION',jsonb_build_object('assignment_id',asgn->>'assignment_id','assignment_event_id',aid,'claim_event_id',cid,'owner_id',a.owner_id,'owner_fence',3,'stop_generation',1,'scope_sha256',a.scope_sha256,'bundle_sha256',bh,'source_http_requests',0,'source_bodies',4,'observation_units',7,'not_after',least(clock_timestamp()+interval '20minutes',(cl->>'expires_at')::timestamptz,(asgn->>'not_after')::timestamptz,a.admitted_until,p.deadline),'original_source_request_deadlines_unchanged',true));
 PERFORM population_top3000_202608_202609_v1.ctx07_jolts_context_v8(normalize_task_id) FROM population_top3000_202608_202609_v1.ctx07_jolts_scope_v8();
 WITH changed AS(UPDATE population_top3000_202608_202609_v1.pipeline_task t SET status='READY',blocker_code=NULL,blocker_until=NULL,not_before=clock_timestamp(),resumption_condition=coalesce(resumption_condition,'{}')||jsonb_build_object('reviewed_parser_bundle_v8',bh,'assignment_event_id',aid,'claim_event_id',cid) FROM population_top3000_202608_202609_v1.ctx07_jolts_scope_v8() s WHERE t.task_id=s.normalize_task_id AND t.status='BLOCKED' AND t.blocker_code='PARSER' RETURNING t.task_id) SELECT jsonb_agg(task_id ORDER BY task_id) INTO released FROM changed;
 SELECT jsonb_build_object('provider_requests',ac.provider_requests,'http_invocations',ac.http_invocations,'stored_bytes',ac.stored_bytes,'reserved_bytes',ac.reserved_bytes,'admitted_until',ac.admitted_until,'deadline',pc.deadline,'tasks',(SELECT jsonb_agg(jsonb_build_object('task_id',t.task_id,'executions',t.executions,'cumulative_failures',t.cumulative_failures,'same_failure_count',t.same_failure_count,'last_failure_fingerprint',t.last_failure_fingerprint,'checkpoint',t.checkpoint) ORDER BY t.task_id) FROM population_top3000_202608_202609_v1.pipeline_task t JOIN population_top3000_202608_202609_v1.ctx07_jolts_scope_v8() s ON s.normalize_task_id=t.task_id)) INTO after_state FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton;
 IF before_state IS DISTINCT FROM after_state OR jsonb_array_length(released)<>4 THEN RAISE EXCEPTION 'CTX07_V8_HISTORY_OR_DENOMINATOR_CHANGED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX07_V8_JOLTS_PARSER_INTEGRATED',jsonb_build_object('assignment_event_id',aid,'claim_event_id',cid,'bundle_sha256',bh,'released_tasks',released,'preserved_counters_history',after_state,'source_http_requests',0,'useful_data_claimed',false,'family_accepted',false,'historical_receipt_qualified',false));
 PERFORM population_top3000_202608_202609_v1.pipeline_wake_v1(a.owner_id,3,'Reviewed exact four retained JOLTS byte parser v8');
END;$register$;
